using PeWorkshop.Core;

namespace PeWorkshop.App;

public sealed record HelpTopic(string Title, string Meaning, string Usage, string Editing);

/// <summary>Offline explanations for the controls and PE structures displayed by the workshop.</summary>
public static class PeHelpCatalog
{
    private static readonly Dictionary<string, HelpTopic> Topics = CreateTopics();

    public static HelpTopic Get(string key) => Topics.TryGetValue(key, out var topic)
        ? topic : throw new KeyNotFoundException($"No PE help topic exists for '{key}'.");
    public static bool Contains(string key) => Topics.ContainsKey(key);

    public static HelpTopic ForField(PeField field)
    {
        ArgumentNullException.ThrowIfNull(field);
        if (field.Group.StartsWith("Section: ", StringComparison.Ordinal))
            return Get("SectionField." + field.Name);
        if (field.Group.StartsWith("Directory: ", StringComparison.Ordinal))
            return Get(field.Name == "VirtualAddress"
                ? field.Group == "Directory: Certificate" ? "CertificateAddress" : "DirectoryAddress"
                : field.Name == "Size" ? "DirectorySize" : throw new KeyNotFoundException(field.Name));
        return Get("Field." + field.Name);
    }

    public static HelpTopic ForDirectory(int index) => index is >= 0 and < 16
        ? Get("Directory." + index) : throw new ArgumentOutOfRangeException(nameof(index));

    public static HelpTopic ForSection(string name)
    {
        ArgumentNullException.ThrowIfNull(name);
        return Topics.TryGetValue("Section." + name, out var topic) ? topic
            : new("Section " + name,
                "A section groups bytes that the loader maps together, such as code or data. Section names are conventions chosen by the producer; an unfamiliar name does not establish what its contents do.",
                "Compare its permissions, file range and memory range to understand where those bytes live. Reveal opens its file-backed bytes for inspection.",
                "Renaming changes only its eight-byte label. It does not transform the contents or change the section's permissions.");
    }

    private static Dictionary<string, HelpTopic> CreateTopics()
    {
        var result = new Dictionary<string, HelpTopic>(StringComparer.Ordinal);
        void Add(string key, string title, string meaning, string usage, string editing) =>
            result.Add(key, new(title, meaning, usage, editing));
        // Pipe-delimited, authored content: key | title | meaning | practical use | editing/limitations.
        foreach (var line in General.Trim().Split('\n'))
        {
            var parts = line.Trim().Split('|');
            Add(parts[0], parts[1], parts[2], parts[3], parts[4]);
        }
        foreach (var line in Fields.Trim().Split('\n'))
        {
            var parts = line.Trim().Split('|');
            Add(parts[0], parts[1], parts[2], parts[3], parts[4]);
        }
        string[] directoryNames = ["Export", "Import", "Resource", "Exception", "Certificate", "Base relocation", "Debug", "Architecture", "Global pointer", "TLS", "Load configuration", "Bound import", "Import address table", "Delay import", "CLR runtime", "Reserved"];
        string[] directoryMeanings = [
            "Lists symbols this image offers to other modules, by name or ordinal, including symbols forwarded elsewhere.",
            "Describes the modules and symbols requested through the ordinary import table when the image is loaded.",
            "Points to a tree of packaged resources, which can include icons, dialogs, version information and localized text.",
            "Points to architecture-specific exception and unwind information used to walk stacks and handle exceptions.",
            "Locates embedded attribute certificate data used by signing systems such as Authenticode. Its address is a file offset, unlike other directories.",
            "Lists locations that need address adjustments when the loader places an image away from its preferred base.",
            "Locates debug records, which may reference a PDB, describe build information or mark a reproducible build.",
            "This directory is reserved by the PE specification and normally has a zero address and size.",
            "Historically identifies a relative address for a global pointer on architectures that use one; it is usually absent in modern desktop images.",
            "Describes thread-local storage: data and optional callbacks associated with individual threads in a process.",
            "Describes loader configuration, potentially including security-related tables and settings whose layout depends on the structure version.",
            "Contains information recorded when imports were bound to particular dependency versions, as a loader optimization.",
            "Locates slots into which the loader writes the resolved addresses of imported functions or data.",
            "Describes dependencies arranged to be resolved when first needed rather than through ordinary load-time imports.",
            "Locates the managed runtime header used by .NET images, including links to metadata and managed execution information.",
            "This last directory slot is reserved and should have a zero address and size. It is not space for a custom feature."];
        string[] directoryUses = [
            "Use Exports to inspect available names, ordinals, RVAs and forwarders; this helps compare a DLL's public binary interface.",
            "Use Imports to inspect declared dependencies and IAT slots. A listed function is not proof that execution calls it, and dynamic loading may add dependencies not listed here.",
            "Reveal can show the corresponding raw bytes. This app does not decode the resource tree or provide an icon, dialog or version-resource editor.",
            "Reveal locates its raw bytes for structural investigation. The app does not decode unwind records or perform stack walking or disassembly.",
            "Use the overview notice and range to identify declared embedded data. The app does not verify trust, signature validity or catalog signatures; absence here does not imply an unsafe file.",
            "Compare this directory with Image base to learn why rebasing involves more than one header value. The app does not apply relocation records.",
            "Reveal locates raw records. The app does not load a PDB, recover source code or decode all debug types; a timestamp alone is not creation-time proof.",
            "A nonzero entry warrants structural investigation, not a conclusion about CPU type. Use Machine in the COFF header for the declared architecture.",
            "Inspect the address in context with the target Machine field. The app shows this descriptor and raw location but does not emulate global-pointer setup.",
            "Reveal can locate the descriptor. The app does not decode TLS templates or callback arrays, and does not execute callbacks while opening a file.",
            "Use the range to locate configuration bytes. The app does not decode individual mitigation settings or establish that a mitigation operates correctly at runtime.",
            "Reveal shows its bytes for comparison. The app does not decode bound descriptors or locate dependency DLLs to validate their recorded identities.",
            "Compare this range with the per-symbol IAT RVA in Imports. The app reads the file's declarations; it does not show addresses resolved in a running process.",
            "Reveal locates raw descriptors. The Imports view currently decodes ordinary imports only, so this directory can explain dependencies absent from that view.",
            "Its presence is a useful clue that managed metadata exists. The app does not decode .NET types, methods, IL or source code.",
            "Check unexpected values against the producing tool's documentation. The app displays the descriptor but does not assign a custom interpretation to it."];
        for (int i = 0; i < directoryNames.Length; i++)
            Add("Directory." + i, directoryNames[i] + " directory", directoryMeanings[i], directoryUses[i],
                i is 7 or 15 ? "Keep reserved values zero. Editing the descriptor does not create a supported structure."
                : i == 4 ? "Changing this range does not sign the image. Editing signed content can invalidate the signature while leaving certificate bytes present."
                : "The address and size describe existing bytes. Changing them does not rebuild the underlying tables; an inconsistent range can prevent loading or make inspection incomplete.");

        string[] names = [".text", ".rdata", ".data", ".bss", ".rsrc", ".reloc", ".pdata", ".idata", ".edata", ".tls"];
        string[] meanings = [
            "Conventionally holds executable machine instructions produced by a compiler and linker.",
            "Conventionally holds read-only data, such as constant strings, tables and sometimes import-related structures.",
            "Conventionally holds initialized writable data, such as global variables with initial values.",
            "Conventionally represents uninitialized data that needs memory but may require few or no stored file bytes.",
            "Conventionally holds the resource tree containing packaged items such as icons, dialogs or version information.",
            "Conventionally holds base relocation records used when the loader changes the image's placement in memory.",
            "Conventionally holds runtime function records used for exception handling and stack unwinding on some architectures.",
            "Conventionally holds import-related tables, although linkers can place imports in sections with other names.",
            "Conventionally holds export tables describing names, ordinals and addresses made available to other modules.",
            "Conventionally holds thread-local data associated with individual threads rather than shared global storage."];
        for (int i = 0; i < names.Length; i++)
            Add("Section." + names[i], names[i] + " section", meanings[i] + " Names are conventions, not proof of content.",
                "Compare its R/W/X permissions and its raw and virtual ranges. Reveal inspects stored bytes; the app does not execute or disassemble them.",
                "Renaming changes only the label. Moving ranges or changing flags requires matching the real contents and all references to them.");
        return result;
    }

    private const string General = """
